  1	package com.pousadamareal;
  2	
  3	import com.pousadamareal.config.DatabaseConfig;
  4	import com.pousadamareal.handlers.*;
  5	import io.javalin.Javalin;
  6	
  7	public class Main {
  8	    public static void main(String[] args) {
  9	        DatabaseConfig.init();
 10	
 11	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 12	        var app = Javalin.create().start(port);
 13	
 14	        app.get("/rooms", RoomHandler::getRooms);
 15	
 16	        app.post("/reservations", ReservationHandler::createReservation);
 17	        app.get("/reservations/{id}", ReservationHandler::getReservation);
 18	        app.post("/reservations/{id}/confirmation", ReservationHandler::confirmReservation);
 19	        app.post("/reservations/{id}/cancellation", ReservationHandler::cancelReservation);
 20	        app.post("/reservations/{id}/check-in", ReservationHandler::checkIn);
 21	        app.post("/reservations/{id}/check-out", ReservationHandler::checkOut);
 22	        app.get("/reservations/{id}/document", ReservationHandler::getDocument);
 23	
 24	        app.get("/messages", MessageHandler::getMessages);
 25	
 26	        app.get("/reports/occupancy", ReportHandler::getOccupancyReport);
 27	        app.get("/reports/revenue", ReportHandler::getRevenueReport);
 28	
 29	        app.exception(Exception.class, (e, ctx) -> {
 30	            e.printStackTrace();
 31	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Erro interno do servidor"));
 32	            ctx.status(500);
 33	        });
 34	    }
 35	
 36	    public record ErrorResponse(String error, String message) {}
 37	}
 38	package com.pousadamareal.handlers;
 39	
 40	import com.google.gson.JsonObject;
 41	import com.google.gson.JsonParser;
 42	import com.pousadamareal.dao.MessageDAO;
 43	import com.pousadamareal.dao.ReservationDAO;
 44	import com.pousadamareal.dao.RoomDAO;
 45	import com.pousadamareal.model.*;
 46	import com.pousadamareal.util.DocumentFormatter;
 47	import com.pousadamareal.util.PriceCalculator;
 48	import io.javalin.http.Context;
 49	
 50	import java.time.LocalDate;
 51	
 52	public class ReservationHandler {
 53	    public static void createReservation(Context ctx) {
 54	        try {
 55	            JsonObject body = JsonParser.parseString(ctx.body()).getAsJsonObject();
 56	
 57	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
 58	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
 59	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Campos obrigatórios faltando"));
 60	                ctx.status(400);
 61	                return;
 62	            }
 63	
 64	            String cpf = body.has("guestCpf") ? body.get("guestCpf").getAsString() : null;
 65	            String cnpj = body.has("companyCnpj") ? body.get("companyCnpj").getAsString() : null;
 66	            String companyName = body.has("companyName") ? body.get("companyName").getAsString() : null;
 67	            String passport = body.has("guestPassport") ? body.get("guestPassport").getAsString() : null;
 68	            String country = body.has("guestCountry") ? body.get("guestCountry").getAsString() : null;
 69	
 70	            int identificationCount = (cpf != null ? 1 : 0) + (cnpj != null ? 1 : 0) + (passport != null ? 1 : 0);
 71	            if (identificationCount != 1) {
 72	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Exatamente um tipo de identificação deve ser fornecido"));
 73	                ctx.status(400);
 74	                return;
 75	            }
 76	
 77	            if (cnpj != null && companyName == null) {
 78	                ctx.json(new ErrorResponse("INVALID_REQUEST", "companyName obrigatório quando companyCnpj é fornecido"));
 79	                ctx.status(400);
 80	                return;
 81	            }
 82	
 83	            if (passport != null && country == null) {
 84	                ctx.json(new ErrorResponse("INVALID_REQUEST", "guestCountry obrigatório quando guestPassport é fornecido"));
 85	                ctx.status(400);
 86	                return;
 87	            }
 88	
 89	            int roomNumber = body.get("roomNumber").getAsInt();
 90	            String guestName = body.get("guestName").getAsString();
 91	            String guestEmail = body.get("guestEmail").getAsString();
 92	            String checkIn = body.get("checkIn").getAsString();
 93	            String checkOut = body.get("checkOut").getAsString();
 94	            int guests = body.get("guests").getAsInt();
 95	            String ratePlan = body.get("ratePlan").getAsString();
 96	
 97	            if (guests < 1) {
 98	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Número de hóspedes deve ser pelo menos 1"));
 99	                ctx.status(400);
100	                return;
101	            }
102	
103	            try {
104	                LocalDate.parse(checkIn);
105	                LocalDate.parse(checkOut);
106	            } catch (Exception e) {
107	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Datas inválidas (formato: yyyy-MM-dd)"));
108	                ctx.status(400);
109	                return;
110	            }
111	
112	            Room room = RoomDAO.getRoomByNumber(roomNumber);
113	            if (room == null) {
114	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Quarto não encontrado"));
115	                ctx.status(404);
116	                return;
117	            }
118	
119	            if (guests > room.capacity()) {
120	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto"));
121	                ctx.status(422);
122	                return;
123	            }
124	
125	            if (!ReservationDAO.isRoomAvailableForDates(roomNumber, checkIn, checkOut)) {
126	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Quarto não disponível para as datas solicitadas"));
127	                ctx.status(409);
128	                return;
129	            }
130	
131	            LocalDate checkInDate = LocalDate.parse(checkIn);
132	            LocalDate checkOutDate = LocalDate.parse(checkOut);
133	            int nights = PriceCalculator.countNights(checkInDate, checkOutDate);
134	
135	            double nightlyRate = PriceCalculator.calculateNightlyRate(checkInDate, room.nightlyRate());
136	            double subtotal = PriceCalculator.calculateSubtotal(nights, nightlyRate);
137	            double discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
138	            double total = PriceCalculator.calculateTotal(subtotal, discount);
139	
140	            Reservation reservation = ReservationDAO.createReservation(
141	                String.valueOf(roomNumber), guestName, guestEmail,
142	                cpf, cnpj, companyName, passport, country,
143	                checkIn, checkOut, guests, ratePlan, nights,
144	                subtotal, discount, total
145	            );
146	
147	            ctx.json(reservation);
148	            ctx.status(201);
149	        } catch (Exception e) {
150	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
151	            ctx.status(500);
152	        }
153	    }
154	
155	    public static void getReservation(Context ctx) {
156	        try {
157	            int id = Integer.parseInt(ctx.pathParam("id"));
158	            Reservation reservation = ReservationDAO.getReservationById(id);
159	
160	            if (reservation == null) {
161	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
162	                ctx.status(404);
163	                return;
164	            }
165	
166	            ctx.json(reservation);
167	        } catch (Exception e) {
168	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
169	            ctx.status(500);
170	        }
171	    }
172	
173	    public static void confirmReservation(Context ctx) {
174	        try {
175	            int id = Integer.parseInt(ctx.pathParam("id"));
176	            Reservation reservation = ReservationDAO.getReservationById(id);
177	
178	            if (reservation == null) {
179	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
180	                ctx.status(404);
181	                return;
182	            }
183	
184	            if (reservation.status != ReservationStatus.PENDING) {
185	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas"));
186	                ctx.status(409);
187	                return;
188	            }
189	
190	            ReservationDAO.updateReservationStatus(id, "CONFIRMED", reservation.total, null);
191	            reservation = ReservationDAO.getReservationById(id);
192	
193	            Room room = RoomDAO.getRoomByNumber(reservation.roomNumber);
194	            String documentText = generateDocument(reservation, room).text;
195	
196	            String emailBody = DocumentFormatter.generateConfirmationEmail(reservation.guestName, documentText);
197	            MessageDAO.saveMessage("EMAIL", reservation.guestEmail, "Reserva confirmada - Pousada Maré Alta", emailBody);
198	
199	            ctx.json(reservation);
200	        } catch (Exception e) {
201	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
202	            ctx.status(500);
203	        }
204	    }
205	
206	    public static void cancelReservation(Context ctx) {
207	        try {
208	            int id = Integer.parseInt(ctx.pathParam("id"));
209	            Reservation reservation = ReservationDAO.getReservationById(id);
210	
211	            if (reservation == null) {
212	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
213	                ctx.status(404);
214	                return;
215	            }
216	
217	            if (reservation.status != ReservationStatus.PENDING && reservation.status != ReservationStatus.CONFIRMED) {
218	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cancelamento não permitido para este status"));
219	                ctx.status(409);
220	                return;
221	            }
222	
223	            double refund = 0;
224	            if (reservation.status == ReservationStatus.CONFIRMED && reservation.ratePlan == RatePlan.STANDARD) {
225	                refund = reservation.total;
226	            }
227	
228	            ReservationDAO.updateReservationStatus(id, "CANCELLED", 0, refund > 0 ? refund : null);
229	            reservation = ReservationDAO.getReservationById(id);
230	
231	            ctx.json(reservation);
232	        } catch (Exception e) {
233	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
234	            ctx.status(500);
235	        }
236	    }
237	
238	    public static void checkIn(Context ctx) {
239	        try {
240	            int id = Integer.parseInt(ctx.pathParam("id"));
241	            Reservation reservation = ReservationDAO.getReservationById(id);
242	
243	            if (reservation == null) {
244	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
245	                ctx.status(404);
246	                return;
247	            }
248	
249	            if (reservation.status != ReservationStatus.CONFIRMED) {
250	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in"));
251	                ctx.status(409);
252	                return;
253	            }
254	
255	            ReservationDAO.updateReservationStatus(id, "CHECKED_IN", reservation.amountPaid, reservation.refund);
256	            reservation = ReservationDAO.getReservationById(id);
257	
258	            ctx.json(reservation);
259	        } catch (Exception e) {
260	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
261	            ctx.status(500);
262	        }
263	    }
264	
265	    public static void checkOut(Context ctx) {
266	        try {
267	            int id = Integer.parseInt(ctx.pathParam("id"));
268	            Reservation reservation = ReservationDAO.getReservationById(id);
269	
270	            if (reservation == null) {
271	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
272	                ctx.status(404);
273	                return;
274	            }
275	
276	            if (reservation.status != ReservationStatus.CHECKED_IN) {
277	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Apenas hóspedes com check-in podem fazer check-out"));
278	                ctx.status(409);
279	                return;
280	            }
281	
282	            ReservationDAO.updateReservationStatus(id, "CHECKED_OUT", reservation.amountPaid, reservation.refund);
283	            reservation = ReservationDAO.getReservationById(id);
284	
285	            Room room = RoomDAO.getRoomByNumber(reservation.roomNumber);
286	            Document doc = generateDocument(reservation, room);
287	
288	            ctx.json(doc);
289	        } catch (Exception e) {
290	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
291	            ctx.status(500);
292	        }
293	    }
294	
295	    public static void getDocument(Context ctx) {
296	        try {
297	            int id = Integer.parseInt(ctx.pathParam("id"));
298	            Reservation reservation = ReservationDAO.getReservationById(id);
299	
300	            if (reservation == null) {
301	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
302	                ctx.status(404);
303	                return;
304	            }
305	
306	            if (reservation.status == ReservationStatus.PENDING) {
307	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Documento só está disponível para reservas pagas"));
308	                ctx.status(409);
309	                return;
310	            }
311	
312	            Room room = RoomDAO.getRoomByNumber(reservation.roomNumber);
313	            Document doc = generateDocument(reservation, room);
314	
315	            ctx.json(doc);
316	        } catch (Exception e) {
317	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
318	            ctx.status(500);
319	        }
320	    }
321	
322	    private static Document generateDocument(Reservation res, Room room) {
323	        String title;
324	        String text;
325	
326	        if (res.guestCpf != null) {
327	            title = "Comprovante de reserva";
328	            text = DocumentFormatter.generateComprovante(res.id, res, room.type());
329	        } else if (res.companyCnpj != null) {
330	            title = "Fatura de hospedagem";
331	            text = DocumentFormatter.generateFatura(res.id, res, room.type());
332	        } else {
333	            title = "Booking receipt";
334	            text = DocumentFormatter.generateBookingReceipt(res.id, res, room.type());
335	        }
336	
337	        return new Document(
338	            title, res.id, res.guestName, res.guestCpf, res.companyCnpj, res.companyName,
339	            res.guestPassport, res.guestCountry, res.roomNumber, room.type(),
340	            res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total, text
341	        );
342	    }
343	
344	    public record ErrorResponse(String error, String message) {}
345	}

