226	            }
227	
228	            ReservationDAO.updateReservationStatus(id, "CANCELLED", 0, refund > 0 ? refund : null);
229	            reservation = ReservationDAO.getReservationById(id);
230	
231	            ctx.json(reservation);
232	        } catch (Exception e) {
233	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
234	            ctx.status(500);
235	        }
236	    }
