238	    public static void checkIn(Context ctx) {
239	        try {
240	            int id = Integer.parseInt(ctx.pathParam("id"));
241	            Reservation reservation = ReservationDAO.getReservationById(id);
242	
243	            if (reservation == null) {
244	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
245	                ctx.status(404);
246	                return;
247	            }
248	
249	            if (reservation.status != ReservationStatus.CONFIRMED) {
250	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in"));
251	                ctx.status(409);
252	                return;
253	            }
254	
255	            ReservationDAO.updateReservationStatus(id, "CHECKED_IN", reservation.amountPaid, reservation.refund);
256	            reservation = ReservationDAO.getReservationById(id);
257	
258	            ctx.json(reservation);
259	        } catch (Exception e) {
260	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
261	            ctx.status(500);
262	        }
