298	public class DatabaseConfig {
299	    private static final String DB_URL = System.getenv("DB_URL");
300	    private static final String DB_USER = System.getenv("DB_USER");
301	    private static final String DB_PASSWORD = System.getenv("DB_PASSWORD");
302	
303	    public static Connection getConnection() throws SQLException {
304	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
305	    }
306	
307	    public static void init() {
308	        try {
309	            Class.forName("org.postgresql.Driver");
310	            executeSqlScript();
311	        } catch (Exception e) {
312	            throw new RuntimeException("Erro ao inicializar banco de dados", e);
313	        }
314	    }
315	
316	    private static void executeSqlScript() throws SQLException {
317	        try (Connection conn = getConnection();
318	             Statement stmt = conn.createStatement()) {
319	
320	            String schema = """
321	                CREATE TABLE IF NOT EXISTS rooms (
322	                    number INTEGER PRIMARY KEY,
323	                    type VARCHAR(50) NOT NULL,
324	                    capacity INTEGER NOT NULL,
325	                    nightly_rate NUMERIC(10, 2) NOT NULL
326	                );
327	
328	                CREATE TABLE IF NOT EXISTS reservations (
329	                    id SERIAL PRIMARY KEY,
330	                    room_number INTEGER NOT NULL,
331	                    guest_name VARCHAR(255) NOT NULL,
332	                    guest_email VARCHAR(255) NOT NULL,
333	                    guest_cpf VARCHAR(20),
334	                    company_cnpj VARCHAR(20),
335	                    company_name VARCHAR(255),
336	                    guest_passport VARCHAR(50),
337	                    guest_country VARCHAR(100),
338	                    check_in DATE NOT NULL,
339	                    check_out DATE NOT NULL,
340	                    guests INTEGER NOT NULL,
341	                    rate_plan VARCHAR(50) NOT NULL,
342	                    nights INTEGER NOT NULL,
343	                    subtotal NUMERIC(10, 2) NOT NULL,
344	                    discount NUMERIC(10, 2) NOT NULL,
345	                    total NUMERIC(10, 2) NOT NULL,
346	                    status VARCHAR(50) NOT NULL,
347	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
348	                    refund NUMERIC(10, 2),
349	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
350	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
351	                );
352	
353	                CREATE TABLE IF NOT EXISTS messages (
354	                    id SERIAL PRIMARY KEY,
355	                    channel VARCHAR(50) NOT NULL,
356	                    recipient_email VARCHAR(255) NOT NULL,
357	                    subject VARCHAR(255) NOT NULL,
358	                    body TEXT NOT NULL,
359	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
360	                );
361	
362	                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
363	                    (101, 'STANDARD', 2, 249.90),
364	                    (102, 'STANDARD', 2, 249.90),
365	                    (201, 'DELUXE', 3, 389.90),
366	                    (202, 'DELUXE', 3, 389.90),
367	                    (301, 'SUITE', 4, 579.90)
368	                ON CONFLICT (number) DO NOTHING;
369	                """;
370	
371	            for (String statement : schema.split(";")) {
372	                if (!statement.trim().isEmpty()) {
373	                    stmt.execute(statement.trim() + ";");
374	                }
375	            }
376	        }
377	    }
378	}

