158	            pstmt.setString(3, checkIn);
159	
160	            try (ResultSet rs = pstmt.executeQuery()) {
161	                if (rs.next()) {
162	                    return rs.getInt("count") == 0;
163	                }
164	            }
165	        }
166	
167	        return false;
