301	    private static final String DB_PASSWORD = System.getenv("DB_PASSWORD");
302	
303	    public static Connection getConnection() throws SQLException {
304	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
305	    }
306	
307	    public static void init() {
308	        try {
309	            Class.forName("org.postgresql.Driver");
310	            executeSqlScript();
311	        } catch (Exception e) {
312	            throw new RuntimeException("Erro ao inicializar banco de dados", e);
313	        }
314	    }
315	
316	    private static void executeSqlScript() throws SQLException {
317	        try (Connection conn = getConnection();
318	             Statement stmt = conn.createStatement()) {
319	
320	            String schema = """
321	                CREATE TABLE IF NOT EXISTS rooms (
322	                    number INTEGER PRIMARY KEY,
323	                    type VARCHAR(50) NOT NULL,
324	                    capacity INTEGER NOT NULL,
325	                    nightly_rate NUMERIC(10, 2) NOT NULL
326	                );
327	
328	                CREATE TABLE IF NOT EXISTS reservations (
329	                    id SERIAL PRIMARY KEY,
330	                    room_number INTEGER NOT NULL,
331	                    guest_name VARCHAR(255) NOT NULL,
332	                    guest_email VARCHAR(255) NOT NULL,
333	                    guest_cpf VARCHAR(20),
