340	                    guests INTEGER NOT NULL,
341	                    rate_plan VARCHAR(50) NOT NULL,
342	                    nights INTEGER NOT NULL,
343	                    subtotal NUMERIC(10, 2) NOT NULL,
344	                    discount NUMERIC(10, 2) NOT NULL,
345	                    total NUMERIC(10, 2) NOT NULL,
346	                    status VARCHAR(50) NOT NULL,
347	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
348	                    refund NUMERIC(10, 2),
349	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
350	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
351	                );
352	
353	                CREATE TABLE IF NOT EXISTS messages (
354	                    id SERIAL PRIMARY KEY,
355	                    channel VARCHAR(50) NOT NULL,
356	                    recipient_email VARCHAR(255) NOT NULL,
357	                    subject VARCHAR(255) NOT NULL,
358	                    body TEXT NOT NULL,
