367	                    (301, 'SUITE', 4, 579.90)
368	                ON CONFLICT (number) DO NOTHING;
369	                """;
370	
371	            for (String statement : schema.split(";")) {
372	                if (!statement.trim().isEmpty()) {
373	                    stmt.execute(statement.trim() + ";");
374	                }
375	            }
376	        }
377	    }
