332	import java.math.BigDecimal;
333	import java.math.RoundingMode;
334	import java.time.LocalDate;
335	
336	public class PriceCalculator {
337	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
338	    private static final double DISCOUNT_RATE = 0.15;
339	
340	    public static double calculateNightlyRate(LocalDate date, double baseRate) {
341	        if (isHighSeason(date)) {
342	            return round(baseRate * HIGH_SEASON_MULTIPLIER);
343	        }
344	        return baseRate;
345	    }
346	
347	    public static boolean isHighSeason(LocalDate date) {
348	        int month = date.getMonthValue();
349	        int day = date.getDayOfMonth();
350	
351	        if (month == 7) return true;
352	        if (month == 12 && day >= 15) return true;
353	        if (month == 1) return true;
354	        if (month == 2) return true;
355	        return false;
356	    }
357	
358	    public static double calculateSubtotal(int nights, double nightlyRate) {
359	        double subtotal = nights * nightlyRate;
360	        return round(subtotal);
361	    }
362	
363	    public static double calculateDiscount(double subtotal, String ratePlan) {
364	        if ("NON_REFUNDABLE".equals(ratePlan)) {
365	            return round(subtotal * DISCOUNT_RATE);
366	        }
367	        return 0.0;
368	    }
369	
370	    public static double calculateTotal(double subtotal, double discount) {
371	        return round(subtotal - discount);
372	    }
373	
374	    public static double round(double value) {
375	        BigDecimal bd = new BigDecimal(value);
376	        return bd.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
377	    }
378	
379	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
380	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
381	    }
382	}
