    12	public class ReportHandler {
    13	    public static void getOccupancyReport(Context ctx) {
    14	        try {
    15	            String date = ctx.queryParam("date");
    16	            if (date == null || date.isEmpty()) {
    17	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'date' obrigatório"));
    18	                ctx.status(400);
    19	                return;
    20	            }
    21	
    22	            try {
    23	                LocalDate.parse(date);
    24	            } catch (Exception e) {
    25	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Data inválida (formato: yyyy-MM-dd)"));
    26	                ctx.status(400);
    27	                return;
    28	            }
    29	
    30	            List<Reservation> reservations = ReservationDAO.getReservationsByDateAndStatus(date, "CONFIRMED");
    31	            List<Reservation> checkedInReservations = ReservationDAO.getReservationsByDateAndStatus(date, "CHECKED_IN");
    32	            List<Reservation> checkedOutReservations = ReservationDAO.getReservationsByDateAndStatus(date, "CHECKED_OUT");
    33	
    34	            reservations.addAll(checkedInReservations);
    35	            reservations.addAll(checkedOutReservations);
    36	
    37	            List<Room> rooms = RoomDAO.getAllRooms();
    38	
    39	            StringBuilder csv = new StringBuilder();
    40	            csv.append("room,type,reservation,check_in,check_out\n");
    41	
    42	            int occupiedCount = 0;
    43	            for (Room room : rooms) {
    44	                boolean occupied = false;
    45	                for (Reservation res : reservations) {
    46	                    if (res.roomNumber == room.number()) {
    47	                        csv.append(room.number()).append(",")
    48	                           .append(room.type()).append(",")
    49	                           .append(res.id).append(",")
    50	                           .append(res.checkIn).append(",")
    51	                           .append(res.checkOut).append("\n");
    52	                        occupied = true;
    53	                        occupiedCount++;
    54	                        break;
    55	                    }
    56	                }
    57	            }
    58	
    59	            csv.append("total,").append(occupiedCount).append("/").append(rooms.size());
    60	
    61	            ctx.contentType("text/csv; charset=utf-8");
    62	            ctx.result(csv.toString());
    63	        } catch (Exception e) {
    64	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
    65	            ctx.status(500);
    66	        }
    67	    }
    68	
    69	    public static void getRevenueReport(Context ctx) {
    70	        try {
    71	            String month = ctx.queryParam("month");
    72	            if (month == null || month.isEmpty()) {
    73	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Parâmetro 'month' obrigatório"));
    74	                ctx.status(400);
    75	                return;
    76	            }
    77	
    78	            try {
    79	                String[] parts = month.split("-");
    80	                if (parts.length != 2) {
    81	                    throw new Exception("Formato inválido");
    82	                }
    83	                Integer.parseInt(parts[0]);
    84	                Integer.parseInt(parts[1]);
    85	            } catch (Exception e) {
    86	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Mês inválido (formato: yyyy-MM)"));
    87	                ctx.status(400);
    88	                return;
    89	            }
    90	
    91	            List<Reservation> reservations = ReservationDAO.getReservationsByMonth(month);
    92	
    93	            StringBuilder csv = new StringBuilder();
    94	            csv.append("reservation,room,check_in,check_out,status,amount\n");
    95	
    96	            double totalAmount = 0;
    97	            for (Reservation res : reservations) {
    98	                double amount = res.amountPaid;
    99	                if (res.refund != null) {
   100	                    amount -= res.refund;
   101	                }
   102	
   103	                csv.append(res.id).append(",")
   104	                   .append(res.roomNumber).append(",")
   105	                   .append(res.checkIn).append(",")
   106	                   .append(res.checkOut).append(",")
   107	                   .append(res.status).append(",")
   108	                   .append(String.format("%.2f", amount)).append("\n");
   109	
   110	                totalAmount += amount;
   111	            }
   112	
   113	            csv.append("total,").append(String.format("%.2f", totalAmount));
   114	
   115	            ctx.contentType("text/csv; charset=utf-8");
   116	            ctx.result(csv.toString());
   117	        } catch (Exception e) {
   118	            ctx.json(new ErrorResponse("INTERNAL_ERROR", e.getMessage()));
   119	            ctx.status(500);
   120	        }
   121	    }
